INSERT INTO tax_tuishui_all (user_name, id_card, phone, pre_deduct, actual_pay, diff_amount, tax_area, merchant, channel, sale, customer_service) SELECT MAX(vy.payee) AS user_name, vy.id_card, MAX(NULLIF(vy.phone, '')) AS phone, COALESCE(SUM(vy.tax_amount), 0) AS pre_deduct, COALESCE(MAX(yi.total_paid_amount), 0) AS actual_pay, COALESCE(SUM(vy.tax_amount), 0) - COALESCE(MAX(yi.total_paid_amount), 0) AS diff_amount, GROUP_CONCAT(DISTINCT NULLIF(vy.tax_area, '') ORDER BY vy.tax_area SEPARATOR ',') AS tax_area, GROUP_CONCAT(DISTINCT NULLIF(vy.merchant, '') ORDER BY vy.merchant SEPARATOR ',') AS merchant, GROUP_CONCAT(DISTINCT NULLIF(vy.channel, '') ORDER BY vy.channel SEPARATOR ',') AS channel, GROUP_CONCAT(DISTINCT NULLIF(vy.sale, '') ORDER BY vy.sale SEPARATOR ',') AS sale, GROUP_CONCAT(DISTINCT NULLIF(vy.customer_service, '') ORDER BY vy.customer_service SEPARATOR ',') AS customer_service FROM v_yukou_all vy LEFT JOIN ( SELECT id_card, COALESCE(SUM(paid_amount), 0) AS total_paid_amount FROM yijiao_info GROUP BY id_card ) yi ON vy.id_card = yi.id_card WHERE vy.id_card IN
#{idCard}
GROUP BY vy.id_card
